string s = "ABZ";
string r = "";
for (int i = 0; i < s.Length; i++)
    r += (char)((s[i] - 'A' + 2) % 26 + 'A');
Console.WriteLine(r);

string s = "XXXYZZ";
string r = "";
int count = 1;
for (int i = 1; i <= s.Length; i++)
{
    if (i < s.Length && s[i] == s[i - 1])
        count++;
    else
    {
        r += s[i - 1] + "" + count;
        count = 1;
    }
}
Console.WriteLine(r);

string s = "level";
bool ok = true;
for (int i = 0; i < s.Length / 2; i++)
    if (s[i] != s[s.Length - 1 - i])
        ok = false;
Console.WriteLine(ok);

